export function adicionarFuncionario(cadastro, funcionario) {
  if (
    typeof funcionario.nome !== 'string' || funcionario.nome.trim() === '' ||
    typeof funcionario.setor !== 'string' || funcionario.setor.trim() === '' ||
    typeof funcionario.salario !== 'number' || !Number.isFinite(funcionario.salario) || funcionario.salario < 0
  ) {
    throw new Error('ficha inválida: nome, setor e salario são obrigatórios (salario >= 0)');
  }
  return [...cadastro, { ...funcionario, id: cadastro.length + 1 }];
}

export function buscarPorSetor(cadastro, setor) {
  return cadastro.filter((funcionario) => funcionario.setor === setor);
}

