export function relatorioPorSetor(cadastro) {
  const relatorio = {};
  for (const funcionario of cadastro) {
    if (!relatorio[funcionario.setor]) {
      relatorio[funcionario.setor] = { quantidade: 0, salarioTotal: 0 };
    }
    relatorio[funcionario.setor].quantidade += 1;
    relatorio[funcionario.setor].salarioTotal += funcionario.salario;
  }
  return relatorio;
}

export function maiorSalario(cadastro) {
  let melhor = null;
  for (const funcionario of cadastro) {
    if (melhor === null || funcionario.salario > melhor.salario) {
      melhor = funcionario;
    }
  }
  return melhor === null ? null : melhor.nome;
}

