import { test } from 'node:test';
import assert from 'node:assert/strict';
import { adicionarFuncionario, buscarPorSetor } from './lib/cadastro.mjs';
import { relatorioPorSetor, maiorSalario } from './lib/relatorio.mjs';

test('adicionarFuncionario adiciona a ficha com id na lista nova', () => {
  const resultado = adicionarFuncionario([], { nome: 'Ana', setor: 'vendas', salario: 3200 });
  assert.deepEqual(resultado, [{ nome: 'Ana', setor: 'vendas', salario: 3200, id: 1 }]);
});

test('adicionarFuncionario não altera a lista nem a ficha originais', () => {
  const cadastro = [{ nome: 'Ana', setor: 'vendas', salario: 3200 }];
  const ficha = { nome: 'Bia', setor: 'ti', salario: 4000 };
  const resultado = adicionarFuncionario(cadastro, ficha);
  assert.equal(cadastro.length, 1);
  assert.equal(ficha.id, undefined);
  assert.equal(resultado.length, 2);
  assert.equal(resultado[1].id, 2);
});

test('adicionarFuncionario recusa ficha incompleta ou com salário inválido', () => {
  assert.throws(() => adicionarFuncionario([], { nome: 'Ana', salario: 3000 }));
  assert.throws(() => adicionarFuncionario([], { nome: '', setor: 'vendas', salario: 3000 }));
  assert.throws(() => adicionarFuncionario([], { nome: 'Ana', setor: 'vendas', salario: -5 }));
});

test('buscarPorSetor devolve só os funcionários do setor pedido', () => {
  const cadastro = adicionarFuncionario([], { nome: 'Ana', setor: 'vendas', salario: 3000 });
  const comCaio = adicionarFuncionario(cadastro, { nome: 'Caio', setor: 'ti', salario: 4000 });
  assert.equal(buscarPorSetor(comCaio, 'ti').length, 1);
  assert.equal(buscarPorSetor(comCaio, 'ti')[0].nome, 'Caio');
  assert.equal(buscarPorSetor(comCaio, 'rh').length, 0);
});

test('relatorioPorSetor agrupa quantidade e soma salários por setor', () => {
  const cadastro = adicionarFuncionario([], { nome: 'Ana', setor: 'vendas', salario: 3000 });
  const comBia = adicionarFuncionario(cadastro, { nome: 'Bia', setor: 'vendas', salario: 3500 });
  const comCaio = adicionarFuncionario(comBia, { nome: 'Caio', setor: 'ti', salario: 4000 });
  assert.deepEqual(relatorioPorSetor(comCaio), {
    vendas: { quantidade: 2, salarioTotal: 6500 },
    ti: { quantidade: 1, salarioTotal: 4000 }
  });
});

test('maiorSalario devolve o nome do maior e listas vazias devolvem o esperado', () => {
  const cadastro = adicionarFuncionario([], { nome: 'Ana', setor: 'vendas', salario: 3000 });
  const comCaio = adicionarFuncionario(cadastro, { nome: 'Caio', setor: 'ti', salario: 4000 });
  assert.equal(maiorSalario(comCaio), 'Caio');
  assert.deepEqual(relatorioPorSetor([]), {});
  assert.equal(maiorSalario([]), null);
});
